pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PhiNFT1155} from "../src/PhiNFT1155.sol";

contract InvMutTest is Test {
    PhiNFT1155 c;
    function setUp() public { c = new PhiNFT1155(); }
    function testFuzz_property(uint256 fuzzedInput) public {
        vm.assume(fuzzedInput < uint256(type(int256).max));
        bool isPaused = c.paused();
        bool isUnpaused = !isPaused;
        assertTrue(isUnpaused);
    }
}
